class Logger {
  constructor() {
    this.catatan = [];
  }
  tulis(pesan) {
    this.catatan.push(pesan);
  }
}
class Keranjang {
  constructor(logger) {
    this.isi = [];
    this.logger = logger;
  }
  tambah(barang) {
    this.isi.push(barang);
    this.logger.tulis(`Tambah ${barang}`);
  }
}
const log = new Logger();
const k = new Keranjang(log);
k.tambah("Buku");
k.tambah("Pensil");
console.log(k.isi.length);
console.log(log.catatan[1]);

