class Baterai {
  constructor(persen) {
    this.persen = persen;
  }
}
class Ponsel {
  constructor(baterai) {
    this.baterai = baterai;
  }
  status() {
    return `Baterai ${this.baterai.persen}%`;
  }
}
const hp = new Ponsel(new Baterai(80));
hp.baterai = new Baterai(100);
console.log(hp.status());

const bisaBicara = {
  bicara() {
    return `${this.nama} bicara`;
  },
};
class Robot {
  constructor(nama) {
    this.nama = nama;
  }
}
const r1 = Object.assign(new Robot("R1"), bisaBicara);
const r2 = new Robot("R2");
console.log(typeof r1.bicara, typeof r2.bicara);

