cards.solution:
class Alamat {
  constructor(kota, kodePos) {
    this.kota = kota;
    this.kodePos = kodePos;
  }
  format() {
    return `${this.kota} ${this.kodePos}`;
  }
}
class Pelanggan {
  constructor(nama, alamat) {
    this.nama = nama;
    this.alamat = alamat;
  }
  label() {
    return `${this.nama}, ${this.alamat.format()}`;
  }
}
const rina = new Pelanggan("Rina", new Alamat("Bandung", "40111"));
console.log(rina.label());
rina.alamat = new Alamat("Malang", "65111");
console.log(rina.label());
